    @Override public void onCreate(Bundle state){super.onCreate(state);lang=getIntent().getStringExtra("language");if(lang==null)lang="nl";Configuration config=new Configuration(getResources().getConfiguration());config.setLocale(Locale.forLanguageTag(lang));words=createConfigurationContext(config);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);WindowCompat.getInsetsController(getWindow(),getWindow().getDecorView()).setAppearanceLightStatusBars(false);mode=ScanModes.normalize(getSharedPreferences("MainActivity",0).getString("codeMode","both"));if(state!=null&&state.getString("package")!=null){File saved=new File(state.getString("package"));try{if(saved.isFile()&&saved.getCanonicalPath().startsWith(new File(getCacheDir(),"exports").getCanonicalPath()+File.separator))packageFile=saved;}catch(IOException ignored){}}String path=state==null?getPreferences(0).getString("lastBox",null):state.getString("folder");if(path!=null&&load(new File(path))){summary();}else countPrompt(false);}
    private String s(String key,Object...args){int id=getResources().getIdentifier("ui_"+key,"string",getPackageName());if(id==0)return key;return args.length==0?words.getString(id):words.getString(id,args);}
    private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
    private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(Color.WHITE);t.setTextSize(size);t.setPadding(dp(4),dp(5),dp(4),dp(5));return t;}
